Sistema: un circuito eléctrico.

Señales: tensiones y corrientes V(t), I(t).

Este enfoque será clave cuando estudiemos los sistemas lineales e invariantes en el tiempo (LTI), que constituyen el núcleo de la asignatura.

import numpy as np

from bokeh.plotting import figure, show, output_notebook
from bokeh.models import ColumnDataSource, CustomJS, Slider, Div, Select, Label
from bokeh.layouts import column, row

output_notebook(verbose=False, hide_banner=True);

# ==============================================================================
# 1. DATOS
# ==============================================================================

t = np.linspace(0, 6, 1200)

# Señal de entrada: seno + pulso rectangular
x = np.sin(2*np.pi*0.7*t) + 0.8*((t > 2.0) & (t < 3.2))

source = ColumnDataSource(data=dict(t=t, x=x, y=x))

# ==============================================================================
# 2. FIGURA
# ==============================================================================

p = figure(
    height=400,
    width=600,
    tools="pan,wheel_zoom,reset",
    title="Una señal de entrada es transformada por un sistema",
    sizing_mode="scale_width" 
)

p.line("t", "x", source=source, line_width=2, color="black",
       alpha=0.45, legend_label="Entrada x(t)")

p.line("t", "y", source=source, line_width=3, color="blue",
       legend_label="Salida y(t)")

p.xaxis.axis_label = "t"
p.yaxis.axis_label = "amplitud"
p.grid.grid_line_alpha = 0.25
p.legend.location = "top_right"
p.legend.click_policy = "hide"
p.toolbar.logo = None

# # Texto tipo caja negra
# block = Div(text="""
# <div style="
#     border: 2px solid #444;
#     border-radius: 10px;
#     padding: 15px;
#     width: 260px;
#     text-align: center;
#     font-family: sans-serif;
#     background-color: #f7f7f7;
# ">
#     <b>Entrada</b> &nbsp; x(t)
#     &nbsp; → &nbsp;
#     <span style="
#         border: 1px solid #333;
#         padding: 6px 12px;
#         border-radius: 6px;
#         background-color: white;
#     ">
#         Sistema
#     </span>
#     &nbsp; → &nbsp;
#     <b>Salida</b> &nbsp; y(t)
# </div>
# """)

# ==============================================================================
# 3. CONTROLES
# ==============================================================================

system_select = Select(
    title="Sistema",
    value="Amplificador",
    options=[
        "Amplificador",
        "Retardo",
        "Suavizado / filtro paso bajo",
        "Saturación no lineal"
    ],
    width=260
)

gain_slider = Slider(start=0.2, end=2.5, value=1.2, step=0.1,
                     title="Ganancia A", width=260)

delay_slider = Slider(start=0.0, end=1.5, value=0.5, step=0.05,
                      title="Retardo τ", width=260)

alpha_slider = Slider(start=0.02, end=0.5, value=0.12, step=0.02,
                      title="Suavizado α", width=260)

sat_slider = Slider(start=0.3, end=2.0, value=0.8, step=0.05,
                    title="Nivel de saturación", width=260)

info = Div(width=600)

# ==============================================================================
# 4. INTERACTIVIDAD
# ==============================================================================

callback = CustomJS(
    args=dict(
        source=source,
        system_select=system_select,
        gain_slider=gain_slider,
        delay_slider=delay_slider,
        alpha_slider=alpha_slider,
        sat_slider=sat_slider,
        info=info
    ),
    code="""
    const data = source.data;
    const t = data["t"];
    const x = data["x"];
    const y = data["y"];

    const system = system_select.value;
    const A = gain_slider.value;
    const tau = delay_slider.value;
    const alpha = alpha_slider.value;
    const sat = sat_slider.value;

    const dt = t[1] - t[0];

    if (system === "Amplificador") {
        for (let i = 0; i < x.length; i++) {
            y[i] = A * x[i];
        }

        info.text = `
        <div style="font-family:sans-serif; font-size:14px;">
        <b>Sistema amplificador:</b> la salida es una versión escalada de la entrada:
        <br>
        <span style="font-size:18px;">y(t) = A x(t)</span>
        <br><br>
        Este sistema es <b>lineal</b>: si duplicamos la entrada, se duplica la salida.
        </div>`;
    }

    else if (system === "Retardo") {
        const shift = Math.round(tau / dt);

        for (let i = 0; i < x.length; i++) {
            if (i - shift >= 0) {
                y[i] = x[i - shift];
            } else {
                y[i] = 0;
            }
        }

        info.text = `
        <div style="font-family:sans-serif; font-size:14px;">
        <b>Sistema con retardo:</b> la salida reproduce la entrada, pero desplazada en el tiempo:
        <br>
        <span style="font-size:18px;">y(t) = x(t - τ)</span>
        <br><br>
        Este sistema no cambia la forma de la señal, solo retrasa cuándo aparece.
        </div>`;
    }

    else if (system === "Suavizado / filtro paso bajo") {
        y[0] = x[0];

        for (let i = 1; i < x.length; i++) {
            y[i] = alpha * x[i] + (1 - alpha) * y[i-1];
        }

        info.text = `
        <div style="font-family:sans-serif; font-size:14px;">
        <b>Filtro paso bajo sencillo:</b> la salida se calcula mezclando la entrada actual
        con la salida anterior:
        <br>
        <span style="font-size:18px;">y[n] = αx[n] + (1-α)y[n-1]</span>
        <br><br>
        El sistema suaviza cambios bruscos y elimina parte de las variaciones rápidas.
        </div>`;
    }

    else if (system === "Saturación no lineal") {
        for (let i = 0; i < x.length; i++) {
            if (x[i] > sat) {
                y[i] = sat;
            } else if (x[i] < -sat) {
                y[i] = -sat;
            } else {
                y[i] = x[i];
            }
        }

        info.text = `
        <div style="font-family:sans-serif; font-size:14px;">
        <b>Sistema con saturación:</b> la salida no puede superar un cierto valor máximo:
        <br>
        <span style="font-size:18px;">y(t) = clip(x(t))</span>
        <br><br>
        Este sistema es <b>no lineal</b>: si aumentamos mucho la entrada, la salida deja de crecer.
        </div>`;
    }

    source.change.emit();
    """
)

for w in [system_select, gain_slider, delay_slider, alpha_slider, sat_slider]:
    w.js_on_change("value", callback)

callback.args["source"].data["y"] = x.copy()

# Ejecutar una vez al cargar
info.text = """
<div style="font-family:sans-serif; font-size:14px;">
<b>Sistema amplificador:</b> la salida es una versión escalada de la entrada:
<br>
<span style="font-size:18px;">y(t) = A x(t)</span>
<br><br>
Este sistema es <b>lineal</b>: si duplicamos la entrada, se duplica la salida.
</div>
"""

controls = column(system_select, gain_slider, delay_slider, alpha_slider, sat_slider)

layout = column(
    p, 
    controls,
    info
)

show(layout)

El valor medio de una señal representa el promedio de sus valores dentro de un intervalo dado.

Señales continuas

Para una señal continua x(t) definida en el intervalo t_1 \le t \le t_2:\bar{x} \overset{\Delta}{=}
\frac{1}{t_2-t_1}
\int_{t_1}^{t_2} x(t)\,dt

Si el intervalo es simétrico respecto al origen,
-T \le t \le T:\bar{x} \overset{\Delta}{=}
\frac{1}{2T}
\int_{-T}^{T} x(t)\,dt

Señales discretas

Para una señal discreta x[n] definida en el intervalo
n_1 \le n \le n_2:\bar{x} \overset{\Delta}{=}
\frac{1}{n_2-n_1+1}
\sum_{n=n_1}^{n_2} x[n]

Si el intervalo es simétrico respecto al origen,
-N \le n \le N:\bar{x} \overset{\Delta}{=}
\frac{1}{2N+1}
\sum_{n=-N}^{N} x[n]

El valor medio total, o simplemente valor medio, describe el promedio de una señal cuando se considera todo su dominio.

Señales continuas

Para una señal continua x(t):x_\text{AV} \overset{\Delta}{=}
\lim_{T\to\infty}
\frac{1}{T}
\int_{-T/2}^{T/2} x(t)\,dt

De forma equivalente:x_\text{AV} \overset{\Delta}{=}
\lim_{T\to\infty}
\frac{1}{2T}
\int_{-T}^{T} x(t)\,dt

Señales discretas

Para una señal discreta x[n]:x_\text{AV} \overset{\Delta}{=}
\lim_{N\to\infty}
\frac{1}{2N+1}
\sum_{n=-N}^{N} x[n]

Si la señal es periódica, su valor medio puede calcularse sobre un único periodo.

Señales continuas

Para una señal continua periódica de periodo T:x_\text{AV} \overset{\Delta}{=}
\frac{1}{T}
\int_{\langle T\rangle} x(t)\,dt

Señales discretas

Para una señal discreta periódica de periodo N:x_\text{AV} \overset{\Delta}{=}
\frac{1}{N}
\sum_{n\in\langle N\rangle} x[n]

El valor de pico mide el valor máximo que alcanza el módulo de una señal.

Señales continuasx_p \overset{\Delta}{=}
\max\{|x(t)|,\ t\in\mathbb{R}\}

Señales discretasx_p \overset{\Delta}{=}
\max\{|x[n]|,\ n\in\mathbb{Z}\}

Señales continuas

En el intervalo t_1\le t\le t_2:E \overset{\Delta}{=}
\int_{t_1}^{t_2} |x(t)|^2\,dt

Para un intervalo simétrico, -T\le t\le T:E_T \overset{\Delta}{=}
\int_{-T}^{T} |x(t)|^2\,dt

Señales discretas

En el intervalo n_1\le n\le n_2:E \overset{\Delta}{=}
\sum_{n=n_1}^{n_2} |x[n]|^2

Para un intervalo simétrico, -N\le n\le N:E_N \overset{\Delta}{=}
\sum_{n=-N}^{N} |x[n]|^2

Potencia media

La potencia media es el valor medio de la potencia instantánea.

En general, la potencia media viene dada por:

Señales continuasP_\infty \overset{\Delta}{=}
\lim_{T\to\infty}
\frac{1}{T}
\int_{-T/2}^{T/2} |x(t)|^2\,dt

De forma equivalente:P_\infty \overset{\Delta}{=}
\lim_{T\to\infty}
\frac{1}{2T}
\int_{-T}^{T} |x(t)|^2\,dt

Señales discretasP_\infty \overset{\Delta}{=}
\lim_{N\to\infty}
\frac{1}{2N+1}
\sum_{n=-N}^{N} |x[n]|^2

Si la señal es periódica, la potencia media puede calcularse sobre un único periodo.

Señales continuas

Para una señal continua periódica de periodo T:P_\infty \overset{\Delta}{=}
\frac{1}{T}
\int_{\langle T\rangle} |x(t)|^2\,dt

Señales discretas

Para una señal discreta periódica de periodo N:P_\infty \overset{\Delta}{=}
\frac{1}{N}
\sum_{n\in\langle N\rangle} |x[n]|^2

Ejemplo: x(t)=2.

P_i(t)=|x(t)|^2=4.E_\infty=\int_{-\infty}^\infty |x(t)|^2 dt=\int_{-\infty}^\infty 4 dt=\infty.P_\infty=\lim_{T\to\infty}\frac{1}{T}\int_{-T/2}^{T/2} P_i(t) dt=\lim_{T\to\infty}\frac{4T}{T}=4.

Según las definiciones de energía y de potencia de una señal, se puede hablar de tres clases de señales:

Señales de energía

Son señales con energía total finita:0<E_\infty<\infty.

Tienen P_\infty=0:P_\infty=\lim_{T\to\infty}\frac{1}{2T}\int_{-T}^{T} |x(t)|^2dt=\lim_{T\to\infty}\frac{E_T}{2T}=0.P_\infty=\lim_{N\to\infty}\frac{1}{2N+1}\sum\limits_{n=-N}^{N} |x[n]|^2=\lim_{N\to\infty}\frac{E_N}{2N+1}=0.

Ejemplo:

E_\infty=1 \Rightarrow P_\infty=0.

Señales de potencia

Son señales con potencia media finita:0<P_\infty<\infty \quad \Rightarrow \quad E_\infty=\infty.

Dado que tienen P_\infty>0, integrando (sumando) en un intervalo infinito, se obtiene E_\infty=\infty.

Ejemplos:

x_1(t)=2.x_2(t): cualquier señal periódica con valor de pico, x_p, finito.

Señales con E_\infty y P_\infty infinitas.

Ejemplo:
x(t)=t.E_\infty=\lim_{T\to\infty}\int_{-T}^{T}|t|^2 dt=\lim_{T\to\infty}\int_{-T}^{T}t^2 dt=\lim_{T\to\infty}\frac{\left.t^3\right|_{-T}^{T}}{3}=
  \lim_{T\to\infty}\frac{2T^3}{3}=\infty.P_\infty=\lim_{T\to\infty}\frac{1}{2T}\int_{-T}^{T}|t|^2 dt=\lim_{T\to\infty}\frac{E_T}{2T}=\lim_{T\to\infty}\frac{2T^3}{6T}=\infty.

%load_ext autoreload
%autoreload 2

import sys
import os
sys.path.append(os.path.abspath(".."))

from utils.plot_helpers import style_math_axes



import numpy as np

from bokeh.plotting import figure, show, output_notebook
from bokeh.models import ColumnDataSource, CustomJS, Select, Div, Slider
from bokeh.layouts import column, row

from utils.plot_helpers import style_math_axes

output_notebook(verbose=False, hide_banner=True)

# ==============================================================================
# 1. EJE TEMPORAL
# ==============================================================================

t_min, t_max = -5.0, 5.0
num_points = 3000
t = np.linspace(t_min, t_max, num_points)

initial_signal = "Senoidal"
A0 = 1.0
T0 = 2.0

# ==============================================================================
# 2. FUNCIÓN AUXILIAR
# ==============================================================================

def compute_signal(name, A, T):

    if name == "Senoidal":
        x = A*np.sin(2*np.pi*t/T)

    elif name == "Cosenoidal con offset":
        x = 0.5*A + A*np.cos(2*np.pi*t/T)

    elif name == "Pulso rectangular":
        x = A*((t >= -T/2) & (t <= T/2)).astype(float)

    elif name == "Exponencial decreciente":
        x = A*np.exp(-t)*(t >= 0)

    elif name == "Gaussiana":
        x = A*np.exp(-t**2)

    elif name == "Señal cuadrada periódica":
        x = A*np.sign(np.sin(2*np.pi*t/T))

    return x

# ==============================================================================
# 3. ESTADO INICIAL
# ==============================================================================

x0 = compute_signal(initial_signal, A0, T0)

p_inst0 = x0**2

mean0 = np.trapezoid(x0, t)/(t_max - t_min)

energy0 = np.trapezoid(p_inst0, t)

peak0 = np.max(np.abs(x0))

if initial_signal == "Senoidal":
    power0 = A0**2/2

elif initial_signal == "Cosenoidal con offset":
    power0 = A0**2/4 + A0**2/2

elif initial_signal == "Señal cuadrada periódica":
    power0 = A0**2

else:
    power0 = 0

source = ColumnDataSource(data=dict(
    t=t,
    x=x0,
    p_inst=p_inst0,
    mean=np.full_like(t, mean0),
    peak_pos=np.full_like(t, peak0),
    p_mean=np.full_like(t, power0),
))

# ==============================================================================
# 4. FIGURA 1: SEÑAL
# ==============================================================================

p1 = figure(
    height=350,
    width=600,
    title="Señal x(t)",
    tools="pan,wheel_zoom,reset"
)

p1.line(
    "t", "x",
    source=source,
    line_width=3,
    color="navy",
    legend_label="x(t)"
)

p1.line(
    "t", "mean",
    source=source,
    line_width=2,
    color="firebrick",
    line_dash="dashed",
    legend_label="valor medio en \nel intervalo mostrado"
)

p1.line(
    "t", "peak_pos",
    source=source,
    line_width=2,
    color="darkorange",
    line_dash="dotdash",
    legend_label="valor de pico"
)

p1.line(
    t,
    np.zeros_like(t),
    color="black",
    alpha=0.4
)

p1.legend.location = "top_right"
p1.legend.click_policy = "hide"

p1.grid.grid_line_alpha = 0.25

style_math_axes(
    p1,
    x_range=(t_min, t_max),
    y_range=(-2.5, 2.5),
    xlabel="t",
    ylabel="x(t)"
)

# ==============================================================================
# 5. FIGURA 2: POTENCIA INSTANTÁNEA
# ==============================================================================

p2 = figure(
    height=320,
    width=600,
    title="Potencia instantánea p(t) = |x(t)|²",
    tools="pan,wheel_zoom,reset"
)

p2.varea(
    x="t",
    y1=0,
    y2="p_inst",
    source=source,
    alpha=0.25,
    color="seagreen",
    legend_label="energía = área bajo p(t)"
)

p2.line(
    "t", "p_inst",
    source=source,
    line_width=3,
    color="seagreen",
    legend_label="p(t) = |x(t)|²"
)

p2.line(
    "t", "p_mean",
    source=source,
    line_width=2,
    color="firebrick",
    line_dash="dashed",
    legend_label="potencia media total"
)

p2.line(
    t,
    np.zeros_like(t),
    color="black",
    alpha=0.4
)

p2.legend.location = "top_right"
p2.legend.click_policy = "hide"

p2.grid.grid_line_alpha = 0.25

style_math_axes(
    p2,
    x_range=(t_min, t_max),
    y_range=(0, 4.5),
    xlabel="t",
    ylabel="p(t)"
)

# ==============================================================================
# 6. CONTROLES
# ==============================================================================

select = Select(
    title="Tipo de señal",
    value=initial_signal,
    options=[
        "Senoidal",
        "Cosenoidal con offset",
        "Pulso rectangular",
        "Exponencial decreciente",
        "Gaussiana",
        "Señal cuadrada periódica",
    ],
    width=250
)

amp_slider = Slider(
    title="Amplitud A",
    start=0.2,
    end=2.0,
    value=A0,
    step=0.1,
    width=150
)

period_slider = Slider(
    title="Periodo / anchura T",
    start=0.5,
    end=5.0,
    value=T0,
    step=0.1,
    width=150
)

# ==============================================================================
# 7. TEXTO INFORMATIVO
# ==============================================================================

info = Div(width=600)

info.text = f"""
<b>Parámetros calculados</b><br>
Valor medio en el intervalo mostrado: {mean0:.3f}<br>
Valor de pico: {peak0:.3f}<br>
Energía en el intervalo mostrado: {energy0:.3f}<br>
Potencia media total: {power0:.3f}
"""

# ==============================================================================
# 8. CALLBACK
# ==============================================================================

callback = CustomJS(
    args=dict(
        source=source,
        select=select,
        amp_slider=amp_slider,
        period_slider=period_slider,
        info=info,
        t_min=t_min,
        t_max=t_max
    ),
    code="""

    const data = source.data;
    const t = data["t"];

    const name = select.value;

    const A = amp_slider.value;
    const T = period_slider.value;

    const x = [];
    const p_inst = [];

    for (let i = 0; i < t.length; i++) {

        const ti = t[i];

        let value = 0;

        // ==========================================================
        // DEFINICIÓN DE LA SEÑAL
        // ==========================================================

        if (name === "Senoidal") {

            value = A*Math.sin(2*Math.PI*ti/T);

        }

        else if (name === "Cosenoidal con offset") {

            value = 0.5*A + A*Math.cos(2*Math.PI*ti/T);

        }

        else if (name === "Pulso rectangular") {

            value = (ti >= -T/2 && ti <= T/2) ? A : 0;

        }

        else if (name === "Exponencial decreciente") {

            value = (ti >= 0) ? A*Math.exp(-ti) : 0;

        }

        else if (name === "Gaussiana") {

            value = A*Math.exp(-ti*ti);

        }

        else if (name === "Señal cuadrada periódica") {

            value = A*Math.sign(Math.sin(2*Math.PI*ti/T));

        }

        x.push(value);

        p_inst.push(value*value);
    }

    // ==============================================================
    // VALOR MEDIO Y ENERGÍA (TRAPECIOS)
    // ==============================================================

    let integral_x = 0;
    let energy = 0;

    for (let i = 0; i < t.length - 1; i++) {

        const dt = t[i+1] - t[i];

        integral_x += 0.5*(x[i] + x[i+1])*dt;

        energy += 0.5*(p_inst[i] + p_inst[i+1])*dt;
    }

    const duration = t_max - t_min;

    const mean = integral_x/duration;

    // ==============================================================
    // POTENCIA MEDIA TOTAL
    // ==============================================================

    let power_mean_total = 0;

    if (name === "Senoidal") {

        power_mean_total = A*A/2;

    }

    else if (name === "Cosenoidal con offset") {

        power_mean_total = A*A/4 + A*A/2;

    }

    else if (name === "Señal cuadrada periódica") {

        power_mean_total = A*A;

    }

    else {

        power_mean_total = 0;
    }

    // ==============================================================
    // VALOR DE PICO
    // ==============================================================

    let peak = 0;

    for (let i = 0; i < x.length; i++) {

        peak = Math.max(peak, Math.abs(x[i]));
    }

    // ==============================================================
    // CLASIFICACIÓN
    // ==============================================================

    let classification = "";

    if (
        name === "Senoidal" ||
        name === "Cosenoidal con offset" ||
        name === "Señal cuadrada periódica"
    ) {

        classification =
        "Es una señal de potencia: su energía total tiende a infinito, pero su potencia media es finita.";
    }

    else {

        classification =
        "Es una señal de energía: su energía total es finita y su potencia media total tiende a cero.";
    }

    // ==============================================================
    // ACTUALIZAR DATOS
    // ==============================================================

    data["x"] = x;

    data["p_inst"] = p_inst;

    data["mean"] = Array(t.length).fill(mean);

    data["peak_pos"] = Array(t.length).fill(peak);

    data["p_mean"] = Array(t.length).fill(power_mean_total);

    // ==============================================================
    // ACTUALIZAR TEXTO
    // ==============================================================

    info.text = `
    <b>Parámetros calculados</b><br>
    Valor medio en el intervalo mostrado: ${mean.toFixed(3)}<br>
    Valor de pico: ${peak.toFixed(3)}<br>
    Energía en el intervalo mostrado: ${energy.toFixed(3)}<br>
    Potencia media total: ${power_mean_total.toFixed(3)}<br><br>
    ${classification}
    `;

    source.change.emit();

"""
)

select.js_on_change("value", callback)

amp_slider.js_on_change("value", callback)

period_slider.js_on_change("value", callback)

# ==============================================================================
# 9. LAYOUT
# ==============================================================================

layout = column(
    p1,
    p2,
    row(select, amp_slider, period_slider),
    info
)

show(layout)

Considerando v_s(t) como la señal de entrada y v_c(t) como la señal de salida, obtenemos:v_s(t)=R i(t)+v_c(t) \quad \Rightarrow\quad i(t)=\frac{v_s(t)-v_c(t)}{R},i(t)=C\frac{d v_c(t)}{dt}.

Por tanto, se obtiene la siguiente ecuación diferencial que relaciona la salida con la entrada del sistema:\frac{d v_c(t)}{dt}+\frac{1}{RC}v_c(t)=\frac{1}{RC}v_s(t).

