    "Rectificador": "y(t) = |x(t)|",
    "Limitador": "y(t) = clip(x(t), -K, K)",
    "Derivador": "y(t) = dx(t)/dt",
    "Integrador": "y(t) = ∫ x(τ)dτ",
}

