# ==============================================================================
# 5. CALLBACK
# ==============================================================================

callback = CustomJS(
    args=dict(
        source=source,
        select=select,
        amp_slider=amp_slider,
        param_slider=param_slider,
        info=info,
        texts=texts
    ),
    code="""
    const data = source.data;
    const t = data["t"];

    const name = select.value;
    const A = amp_slider.value;
    const a = param_slider.value;

    const x_real = [];
    const x_imag = [];
    const y_real = [];
    const y_imag = [];

    function xreal(u) {
        return Math.exp(-0.35*(u + 1.0)*(u + 1.0))
             * Math.cos(2*Math.PI*0.45*u);
    }

    function ximag(u) {
        return 0.6*Math.exp(-0.25*(u - 0.8)*(u - 0.8))
             * Math.sin(2*Math.PI*0.65*u);
    }

    for (let i = 0; i < t.length; i++) {

        const ti = t[i];

        const xr = A*xreal(ti);
        const xi = A*ximag(ti);

        let yr = xr;
        let yi = xi;

        if (name === "Desplazamiento temporal") {
            yr = A*xreal(ti - a);
            yi = A*ximag(ti - a);
        }

        else if (name === "Adelanto temporal") {
            yr = A*xreal(ti + a);
            yi = A*ximag(ti + a);
        }

        else if (name === "Inversión temporal") {
            yr = A*xreal(-ti);
            yi = A*ximag(-ti);
        }

        else if (name === "Escalado temporal") {
            yr = A*xreal(a*ti);
            yi = A*ximag(a*ti);
        }

        else if (name === "Compresión temporal") {
            yr = A*xreal(a*ti);
            yi = A*ximag(a*ti);
        }

        else if (name === "Expansión temporal") {
            yr = A*xreal(ti/a);
            yi = A*ximag(ti/a);
        }

        else if (name === "Escalado de amplitud") {
            yr = a*A*xreal(ti);
            yi = a*A*ximag(ti);
        }

        else if (name === "Conjugación compleja") {
            yr = xr;
            yi = -xi;
        }

        x_real.push(xr);
        x_imag.push(xi);
        y_real.push(yr);
        y_imag.push(yi);
    }

    data["x_real"] = x_real;
    data["x_imag"] = x_imag;
    data["y_real"] = y_real;
    data["y_imag"] = y_imag;

    info.text = `
    <b>${name}</b><br>
    <span style="font-size:18px;">${texts[name]}</span><br><br>
    Línea continua: parte real. Línea discontinua: parte imaginaria.
    `;

    source.change.emit();
    """
)

select.js_on_change("value", callback)
amp_slider.js_on_change("value", callback)
param_slider.js_on_change("value", callback)

layout = column(
    p,
    row(select, amp_slider, param_slider),
    info
)

show(layout)







