    let beta_text = "";

    if (beta !== 0) {
        beta_text = "<br><br>Además, β ≠ 0 produce un desplazamiento discreto.";
    }

    info.text = `
    <b>Transformación discreta</b><br>
    <span style="font-size:18px;">
    y[n] = x[${alpha}n ${beta >= 0 ? "+" : "-"} ${Math.abs(beta)}]
