y_init = np.zeros_like(t_vec)
for i, amp in enumerate(init_amps):
    if amp > 0: y_init += amp * np.sin(2 * np.pi * (i+1) * f0 * t_vec)
if np.max(np.abs(y_init)) > 0: y_init /= np.max(np.abs(y_init))

