# 2. DATOS
# ==========================================
melody_rock = [164.8, 164.8, 196.0, 164.8, 146.8, 130.8, 110.0, 110.0]
# Himno de la Alegría (Ode to Joy)
# Mi, Mi, Fa, Sol, Sol, Fa, Mi, Re, Do, Do, Re, Mi, Mi, Re, Re
