def get_y_time_scaled(t_arr, w_base, d_base, td, sc):
    y = np.zeros_like(t_arr)
    w_current = w_base * sc
    for k_pulse in range(-15, 16):
        center = sc * (k_pulse * d_base + td)
        sign = 1 if k_pulse % 2 == 0 else -1
        val = np.maximum(0, 1 - np.abs(t_arr - center)/w_current)
        y += sign * val
    return y

